CREATE SCHEMA IF NOT EXISTS davomat;
CREATE TABLE IF NOT EXISTS davomat.organizations(id uuid PRIMARY KEY,name text NOT NULL);
CREATE TABLE IF NOT EXISTS davomat.branches(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES davomat.organizations(id),name text NOT NULL,latitude double precision NOT NULL,longitude double precision NOT NULL,radius_m integer NOT NULL DEFAULT 150,max_accuracy_m integer NOT NULL DEFAULT 50);
CREATE TABLE IF NOT EXISTS davomat.users(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES davomat.organizations(id),branch_id uuid REFERENCES davomat.branches(id),login varchar(8) NOT NULL UNIQUE CHECK(login ~ '^[0-9]{8}$'),password_hash text NOT NULL,first_name text NOT NULL,last_name text NOT NULL,position text NOT NULL,role text NOT NULL CHECK(role IN ('owner','admin','teacher','accountant')),status text NOT NULL DEFAULT 'active',must_change_password boolean NOT NULL DEFAULT true,avatar_id uuid,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS davomat.auth_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES davomat.users(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS davomat.login_attempts(key text PRIMARY KEY,count integer NOT NULL,window_start timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS davomat.rates(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES davomat.users(id),effective_from date NOT NULL,hourly_rate numeric(14,2) NOT NULL CHECK(hourly_rate>=0),UNIQUE(user_id,effective_from));
CREATE TABLE IF NOT EXISTS davomat.lessons(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES davomat.organizations(id),branch_id uuid NOT NULL REFERENCES davomat.branches(id),teacher_id uuid NOT NULL REFERENCES davomat.users(id),subject text NOT NULL,group_name text NOT NULL,room text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'scheduled',CHECK(ends_at>starts_at));
CREATE INDEX IF NOT EXISTS lesson_date ON davomat.lessons(org_id,starts_at);
CREATE TABLE IF NOT EXISTS davomat.evidence(id uuid PRIMARY KEY,org_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES davomat.users(id),kind text NOT NULL,path text NOT NULL,mime text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),used boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS davomat.challenges(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES davomat.users(id),expires_at timestamptz NOT NULL,used boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS davomat.attendance(id uuid PRIMARY KEY,org_id uuid NOT NULL,branch_id uuid NOT NULL REFERENCES davomat.branches(id),teacher_id uuid NOT NULL REFERENCES davomat.users(id),lesson_id uuid NOT NULL UNIQUE REFERENCES davomat.lessons(id),state text NOT NULL CHECK(state IN('active','paused','completed','cancelled')),approval text NOT NULL CHECK(approval IN('pending','approved','rejected')),started_at timestamptz NOT NULL,ended_at timestamptz,planned_start timestamptz NOT NULL,planned_end timestamptz NOT NULL,hourly_rate numeric(14,2) NOT NULL,breaks jsonb NOT NULL DEFAULT '[]',reason text,start_evidence uuid REFERENCES davomat.evidence(id),end_evidence uuid REFERENCES davomat.evidence(id),start_location jsonb,end_location jsonb,version integer NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS single_open_attendance ON davomat.attendance(teacher_id) WHERE state IN('active','paused');
CREATE INDEX IF NOT EXISTS attendance_date ON davomat.attendance(org_id,started_at);
CREATE TABLE IF NOT EXISTS davomat.operations(user_id uuid NOT NULL,key text NOT NULL,route text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS davomat.corrections(id uuid PRIMARY KEY,org_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES davomat.users(id),attendance_id uuid NOT NULL REFERENCES davomat.attendance(id),proposed_start timestamptz NOT NULL,proposed_end timestamptz NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'pending',reviewer_id uuid,review_reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS davomat.payroll(id uuid PRIMARY KEY,org_id uuid NOT NULL,branch_id uuid REFERENCES davomat.branches(id),month text NOT NULL,version integer NOT NULL,state text NOT NULL DEFAULT 'draft',items jsonb NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,UNIQUE(org_id,branch_id,month,version));
CREATE TABLE IF NOT EXISTS davomat.audit(id uuid PRIMARY KEY,org_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,entity_id text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON SCHEMA davomat FROM PUBLIC;

